package org.sleepwell.app;
import android.app.Activity;import android.content.*;import android.os.*;import android.print.*;import android.view.*;import android.widget.*;import android.text.*;import java.util.*;
/** Fresh random printable QR draft. Export and enrollment are separate explicit actions. */
public final class GeneratedMorningQrActivity extends Activity implements GeneratedMorningQrJob.Observer {
 private static final int PNG=833,PDF=834;private GeneratedMorningQrJob job;private String request,labelDraft,error="";private boolean resumed,keptCopy;private Button png,pdf,print,use,update;private GeneratedMorningQrJob.State rendered;
 static Intent create(Activity activity,String label,String request){return new Intent(activity,GeneratedMorningQrActivity.class).putExtra("label",label).putExtra("request",request);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);setResult(RESULT_CANCELED);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();labelDraft=saved==null?getIntent().getStringExtra("label"):saved.getString("label");if(saved==null){try{labelDraft=MorningCode.label(labelDraft);}catch(IllegalArgumentException empty){labelDraft="Morning code";}}else if(labelDraft==null||labelDraft.length()>120)labelDraft="Morning code";keptCopy=saved!=null&&saved.getBoolean("keptCopy",false);Object retained=getLastNonConfigurationInstance();if(retained instanceof GeneratedMorningQrJob existing)job=existing;else job=new GeneratedMorningQrJob(getApplicationContext(),saved==null?GeneratedMorningQr.create():GeneratedMorningQr.validate(saved.getString("payload")),saved==null?labelDraft:saved.getString("preparedLabel","Morning code"),saved!=null);job.observe(this);}catch(Exception invalid){finish();}}
 @Override public Object onRetainNonConfigurationInstance(){return job;}
 public void changed(GeneratedMorningQrJob.State state){if(isDestroyed())return;rendered=state;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Create a printable code",this::back);Design.space(body,12);Design.text(body,"A random code made on this phone. Exporting it does not change any alarm or enrolled target.",14,400,Design.MUTED);Design.space(body,12);Design.text(body,"Location name",13,500,Design.MUTED);EditText name=new EditText(this);name.setSingleLine(true);name.setText(labelDraft);name.setHint("Bathroom");name.setContentDescription("Generated code location name");name.setTypeface(Design.font(this,400));name.setTextSize(16*Appearance.scale(this));name.setTextColor(Design.INK);name.setBackground(Design.outline(this,Design.CREAM,Design.LINE,12));Design.pad(name,14,12);name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});body.addView(name);name.setEnabled(!state.busy());name.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){labelDraft=s.toString();controls();}public void afterTextChanged(Editable editable){}});Design.space(body,10);update=Design.button(body,"Update printable label",false,()->{try{labelDraft=MorningCode.label(labelDraft);error="";job.prepare(labelDraft);}catch(IllegalArgumentException invalid){error=invalid.getMessage();changed(job.state());}});if(state.document!=null){ImageView image=new ImageView(this);image.setImageBitmap(state.document.preview);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setBackgroundColor(android.graphics.Color.WHITE);image.setContentDescription("Generated morning QR, "+state.document.label);body.addView(image,new LinearLayout.LayoutParams(-1,Design.dp(this,320)));Design.space(body,8);Design.text(body,"Target fingerprint · "+state.document.hash.substring(0,16)+"…",11,400,Design.MUTED);}Design.space(body,10);Design.text(body,"Keep a readable copy before enrolling it. Only the label and hash go into the alarm; the printed code cannot be recreated later from that hash.",13,500,Design.BROWN);Design.space(body,8);Design.text(body,"Anyone with the exported PNG/PDF can use this code for the challenge. No website, camera or network is opened by generation. Save files to a destination you choose.",12,400,Design.MUTED);Design.space(body,10);png=Design.button(body,"Save PNG",false,()->choose("png"));pdf=Design.button(body,"Save PDF",false,()->choose("pdf"));print=Design.button(body,"Print with Android",false,this::print);if(state.phase==GeneratedMorningQrJob.Phase.WRITING)Design.button(body,"Cancel export",false,job::cancelWrite);if(state.phase==GeneratedMorningQrJob.Phase.ERROR)Design.button(body,"Prepare again",false,()->{try{error="";job.prepare(MorningCode.label(labelDraft));}catch(IllegalArgumentException invalid){error=invalid.getMessage();changed(job.state());}});Design.space(body,10);Switch copy=new Switch(this);copy.setText("I have kept a readable copy");copy.setTextSize(13*Appearance.scale(this));copy.setTypeface(Design.font(this,400));copy.setTextColor(Design.INK);copy.setMinHeight(Design.dp(this,48));copy.setChecked(keptCopy);copy.setEnabled(!state.busy());copy.setOnCheckedChangeListener((button,value)->{keptCopy=value;controls();});body.addView(copy);Design.space(body,8);Design.text(body,error.isEmpty()?state.message:error,13,500,Design.BROWN);LinearLayout footer=RecordUi.footer(body);use=Design.button(footer,"Use generated code",true,this::use);Design.button(footer,"Cancel",false,this::back);controls();}
 private boolean prepared(){if(job==null||rendered==null||rendered.phase!=GeneratedMorningQrJob.Phase.READY||rendered.document==null)return false;try{return rendered.document.label.equals(MorningCode.label(labelDraft));}catch(IllegalArgumentException invalid){return false;}}
 private void controls(){if(png==null)return;boolean ready=prepared();png.setEnabled(ready);pdf.setEnabled(ready);print.setEnabled(ready);use.setEnabled(ready&&keptCopy);update.setEnabled(rendered!=null&&!rendered.busy());}
 private void choose(String format){if(!resumed||!hasWindowFocus()||!prepared()||!job.choose(format))return;error="";try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(format.equals("png")?"image/png":"application/pdf").putExtra(Intent.EXTRA_TITLE,"SleepWell-morning-code."+format),format.equals("png")?PNG:PDF);}catch(ActivityNotFoundException unavailable){job.cancelChoice();error="Android Files is unavailable. Enable a document picker and try again.";changed(job.state());}}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code!=PNG&&code!=PDF)return;if(result!=RESULT_OK||data==null||data.getData()==null||data.getClipData()!=null||data.getSelector()!=null){job.cancelChoice();return;}job.write(data.getData(),code==PNG?"png":"pdf");}
 private void print(){if(!resumed||!hasWindowFocus()||!prepared())return;PrintManager manager=getSystemService(PrintManager.class);if(manager==null){error="Android printing is unavailable. Save a PDF or PNG instead.";changed(job.state());return;}error="";if(!job.beginPrint())return;try{manager.print("SleepWell morning QR",new PrintDocumentAdapter(){private PrintAttributes layout;public void onLayout(PrintAttributes oldAttributes,PrintAttributes newAttributes,CancellationSignal cancellation,LayoutResultCallback callback,Bundle extras){if(cancellation.isCanceled()){callback.onLayoutCancelled();return;}layout=newAttributes;callback.onLayoutFinished(new PrintDocumentInfo.Builder("SleepWell-morning-code.pdf").setPageCount(1).setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).build(),true);}public void onWrite(PageRange[] pages,ParcelFileDescriptor destination,CancellationSignal cancellation,WriteResultCallback callback){job.writePrint(destination,cancellation,callback,layout);}public void onFinish(){job.finishPrint();}},new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setColorMode(PrintAttributes.COLOR_MODE_MONOCHROME).build());}catch(RuntimeException unavailable){job.finishPrint();error="Print preview could not open. Save a PDF instead.";changed(job.state());}}
 private void use(){if(!resumed||!hasWindowFocus()||!prepared()||!keptCopy)return;GeneratedMorningQr.Document document=job.state().document;setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("label",document.label).putExtra("hash",document.hash));finish();}
 private void back(){setResult(RESULT_CANCELED);finish();}
 @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
 @Override protected void onResume(){super.onResume();resumed=true;}
 @Override protected void onPause(){resumed=false;super.onPause();}
 @Override protected void onNewIntent(Intent input){super.onNewIntent(input);setResult(RESULT_CANCELED);finish();}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(job!=null){state.putString("payload",job.payload);state.putString("preparedLabel",job.state().document==null?"Morning code":job.state().document.label);state.putString("label",labelDraft);state.putBoolean("keptCopy",keptCopy);}}
 @Override protected void onDestroy(){if(job!=null){job.detach(this);if(!isChangingConfigurations())job.close();}super.onDestroy();}
 @Override protected void onPostResume(){super.onPostResume();RecordUi.lightBars(this);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
